def synch_request(request, timeout \\ 5000) when is_binary(request) or is_map(request) do
  async_request(request, self())

  receive do
    {:response, response} -> {:ok, {:response, response}}
    {:error, error} -> {:error, error}
  after
    timeout -> {:error, :timeout}
  end
end

def start(_type, _args) do
  children = [
    %{
      id: Envio.Registry,
      start:
        {Registry, :start_link,
         [[keys: :duplicate, name: Envio.Registry, partitions: System.schedulers_online()]]}
    },
    phoenix_pubsub_spec(),
    %{id: Envio.Channels, start: {Envio.Channels, :start_link, []}},
    %{id: Envio.Backends, start: {Envio.Backends, :start_link, []}}
  ]

  Supervisor.start_link(children, strategy: :one_for_one)
end

