def release(key, how_many \\ 1) do
  Enum.reduce_while(1..how_many, :ok, fn _, :ok ->
    case :ets.select_replace(__MODULE__, [
           {{:"$1", :"$2", :"$3", :"$4"},
            [{:andalso, {:==, :"$1", key}, {:"=<", {:+, :"$3", 1}, :"$2"}}],
            [{{:"$1", :"$2", {:+, :"$3", 1}, :"$4"}}]}
         ]) do
      0 -> {:halt, :error}
      1 -> {:cont, :ok}
    end
  end)
end

