def parse(timing) do
  withl(
    split: [start, stop] <- String.split(timing, " "),
    parse_start: {start, ""} <- Integer.parse(start),
    parse_stop: {stop, ""} <- Integer.parse(stop)
  ) do
    timing = %__MODULE__{start_time: start, stop_time: stop}
    {:ok, timing}
  else
    [split: _error] -> {:error, :invalid_timing}
    [parse_start: _error] -> {:error, :time_nan}
    [parse_stop: _error] -> {:error, :time_nan}
  end
end

def parse_config(config_string) do
  case Base.decode16(config_string) do
    {:ok, config} -> {:ok, config}
    :error -> {:error, :invalid_config}
  end
end

def parse_mode(mode_string) do
  case mode_string do
    "generic" -> {:ok, :generic}
    "CELP-cbr" -> {:ok, :CELP_cbr}
    "CELP-vbr" -> {:ok, :CELP_vbr}
    "AAC-lbr" -> {:ok, :AAC_lbr}
    "AAC-hbr" -> {:ok, :AAC_hbr}
    _other -> {:error, :invalid_mode}
  end
end

def parse_numeric_bool_string(string) do
  case Integer.parse(string) do
    {0, ""} -> {:ok, false}
    {1, ""} -> {:ok, true}
    _string_not_0_nor_1 -> {:error, :string_not_0_nor_1}
  end
end

def parse_numeric_hex_string(string) do
  case Integer.parse(string, 16) do
    {number, ""} -> {:ok, number}
    _string_not_hex -> {:error, :string_not_hex}
  end
end

def parse_numeric_string(string) do
  case Integer.parse(string) do
    {number, ""} -> {:ok, number}
    _string_nan -> {:error, :string_nan}
  end
end

def parse_payload_type(pt_string) do
  case Integer.parse(pt_string) do
    {pt, ""} when pt >= 0 and pt <= 127 -> {:ok, pt}
    _otherwise -> {:error, :invalid_pt}
  end
end

def parse_sprop_ps(pss) do
  pss
  |> String.split(",")
  |> Enum.reduce_while({:ok, []}, fn parameter_set, {:ok, acc} ->
    case Base.decode64(parameter_set) do
      {:ok, decoded} -> {:cont, {:ok, acc ++ [decoded]}}
      :error -> {:halt, {:error, :invalid_ps}}
    end
  end)
end

def split(origin, delim, expected_len) do
  split = String.split(origin, delim)

  cond do
    length(split) == expected_len -> {:ok, split}
    length(split) < expected_len -> {:error, :too_few_fields}
    length(split) > expected_len -> {:error, :too_many_fields}
  end
end

