def generate_enum_native_definition({enum_name, enum_types}, _ctx) do
  enum_types =
    Enum.map_join(enum_types, ",\n", fn
      {type, val} -> String.upcase("#{enum_name}_#{type} = #{val}")
      type -> String.upcase("#{enum_name}_#{type}")
    end)

  enum_name = enum_name |> Atom.to_string() |> Macro.camelize()

  ~g"""
  #ifdef __cplusplus
    enum #{enum_name}{
      #{enum_types}
    };
  #else
    enum #{enum_name}_t{
      #{enum_types}
    };
    typedef enum #{enum_name}_t #{enum_name};
  #endif
  """
end

def generate_struct_native_definition(
      {struct_type_name, _struct_module_name, struct_fields},
      code_generator,
      ctx
    ) do
  struct_fields_definition =
    struct_fields
    |> Enum.map(fn {field_name, field_type} ->
      BaseType.generate_declaration(field_type, field_name, code_generator, ctx)
    end)
    |> Enum.map(&Bunch.listify/1)
    |> Enum.flat_map(fn x -> x end)
    |> Enum.map_join("\n", fn declaration -> ~g<#{declaration};> end)

  ~g"""
  #ifdef __cplusplus
    struct #{struct_type_name} {
      #{struct_fields_definition}
    };
  #else
    struct #{struct_type_name}_t {
      #{struct_fields_definition}
    };
    typedef struct #{struct_type_name}_t #{struct_type_name};
  #endif
  """
end

def mods_to_opts(modifiers) do
  modifiers
  |> Enum.map(fn
    97 -> {:keys, :atoms}
    65 -> {:keys, :atoms!}
    114 -> {:strings, :reference}
    99 -> {:strings, :copy}
    m -> raise ArgumentError, "unknown sigil modifier #{<<34, m, 34>>}"
  end)
end

def refresh_entity(url, entity, options) do
  force_fetch = Keyword.get(options, :force, false)

  if force_fetch and not are_same_origin?(url, Endpoint.url()) do
    Logger.debug("Entity is external and we want a force fetch")

    case Fetcher.fetch_and_update(url, options) do
      {:ok, _activity, entity} -> {:ok, entity}
      {:error, :http_gone} -> {:error, :http_gone, entity}
      {:error, :http_not_found} -> {:error, :http_not_found, entity}
      {:error, err} -> {:error, err}
    end
  else
    {:ok, entity}
  end
end

